/**
 * FCPT Commands Entry Point
 * Temporarily simplified to get UI working
 */

/// <reference types="office-js" />

Office.onReady((info) => {
  if (info.host === Office.HostType.PowerPoint) {
    console.log('[FCPT] Commands initialized for PowerPoint');
    console.log('[FCPT] Platform:', info.platform);
  }
});

export async function showAbout(event: Office.AddinCommands.Event): Promise<void> {
  alert('FCPT - Fast Consulting PowerPoint Tools v1.0.0');
  event.completed();
}

export async function showHelp(event: Office.AddinCommands.Event): Promise<void> {
  alert('FCPT Help - Visit github.com/fcpt/fcpt-office-addin for documentation');
  event.completed();
}

// Make functions globally available for ribbon
(global as any).showAbout = showAbout;
(global as any).showHelp = showHelp;
